GRID_SIZE = 20
FPS = 30
MAX_AGENTS_PER_TEAM = 5
MAX_LEVELS = 3

# Agent roles
ROLE_ATTACKER = "attacker"
ROLE_DEFENDER = "defender"
ROLE_SCOUT = "scout"

# Ability types
ABILITY_SPEED_BOOST = "speed_boost"
ABILITY_HEAL = "heal"
ABILITY_SHIELD = "shield"

# Game modes
MODE_CTF = "capture_the_flag"
MODE_DEFEND = "defend_base"
MODE_ELIMINATION = "elimination"

# =============================================================================
# Data Structures
# =============================================================================

class Position:
    def __init__(self, x: int, y: int):
        self.x = x
        self.y = y

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)

    def __eq__(self, other):
        return isinstance(other, Position) and self.x == other.x and self.y == other.y

    def __hash__(self):
        return hash((self.x, self.y))

    def __repr__(self):
        return f"Position({self.x}, {self.y})"


class Agent:
    def __init__(self, agent_id: str, role: str, team: str, position: Position):
        self.id = agent_id
        self.role = role
        self.team = team
        self.position = position
        self.health = 100
        self.max_health = 100
        self.shield = 0
        self.speed_multiplier = 1.0
        self.cooldowns = {}
        self.state = "idle"  # idle, moving, attacking, capturing, returning, defending
        self.target = None
        self.last_known_enemies: List[Position] = []
        self.last_speech = None

    def move_toward(self, target: Position, grid: 'GameGrid') -> bool:
        """Move one step toward target using BFS if blocked."""
        if self.position == target:
            return True

        # Simple movement: try direct step first
        dx = 0 if target.x == self.position.x else (1 if target.x > self.position.x else -1)
        dy = 0 if target.y == self.position.y else (1 if target.y > self.position.y else -1)

        # Try moving diagonally first if both dx and dy are non-zero
        if dx != 0 and dy != 0:
            if grid.is_valid_move(self.position.x + dx, self.position.y + dy):
                self.position.x += dx
                self.position.y += dy
                return True
            elif grid.is_valid_move(self.position.x + dx, self.position.y):
                self.position.x += dx
                return True
            elif grid.is_valid_move(self.position.x, self.position.y + dy):
                self.position.y += dy
                return True

        # Try cardinal directions
        for dx, dy in [(dx, 0), (0, dy)]:
            if dx == 0 and dy == 0:
                continue
            if grid.is_valid_move(self.position.x + dx, self.position.y + dy):
                self.position.x += dx
                self.position.y += dy
                return True

        # If blocked, try pathfinding
        path = grid.find_path(self.position, target)
        if path and len(path) > 0:
            next_pos = path[0]
            self.position = next_pos
            return True

        return False

    def use_ability(self, ability: str, target_agent: Optional['Agent'] = None):
        """Apply ability effect."""
        if ability == ABILITY_SPEED_BOOST:
            self.speed_multiplier = 1.5
            self.cooldowns[ABILITY_SPEED_BOOST] = 10
        elif ability == ABILITY_HEAL:
            if target_agent:
                target_agent.health = min(target_agent.max_health, target_agent.health + 30)
                self.cooldowns[ABILITY_HEAL] = 15
        elif ability == ABILITY_SHIELD:
            self.shield = 25
            self.cooldowns[ABILITY_SHIELD] = 12

    def update_cooldowns(self):
        for key in list(self.cooldowns.keys()):
            self.cooldowns[key] -= 1
            if self.cooldowns[key] <= 0:
                del self.cooldowns[key]
        if ABILITY_SPEED_BOOST not in self.cooldowns:
            self.speed_multiplier = 1.0

    def take_damage(self, amount: int):
        if self.shield > 0:
            self.shield = max(0, self.shield - amount)
            amount = 0
        self.health -= amount

    def is_alive(self) -> bool:
        return self.health > 0


class GameGrid:
    def __init__(self, width: int, height: int, obstacles: Set[Position] = None):
        self.width = width
        self.height = height
        self.obstacles = obstacles or set()

    def is_valid_move(self, x: int, y: int) -> bool:
        return (0 <= x < self.width and
                0 <= y < self.height and
                Position(x, y) not in self.obstacles)

    def find_path(self, start: Position, goal: Position) -> Optional[List[Position]]:
        """A* pathfinding."""
        if not self.is_valid_move(start.x, start.y) or not self.is_valid_move(goal.x, goal.y):
            return None

        open_set = [(0, start)]
        came_from = {}
        g_score = {start: 0}
        f_score = {start: start.distance_to(goal)}

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                # Reconstruct path
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                return list(reversed(path))

            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                neighbor = Position(current.x + dx, current.y + dy)
                if not self.is_valid_move(neighbor.x, neighbor.y):
                    continue

                tentative_g = g_score[current] + 1
                if neighbor not in g_score or tentative_g < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    f_score[neighbor] = tentative_g + neighbor.distance_to(goal)
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))

        return None


